v.fn(x => T - x, { color: H.colors.accent, width: 3 });
v.fn(x => M - a * x, { color: H.colors.accent2, width: 3 });
H.text("Word problem: x + y = total,  a·x + y = money", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
// subtract: (a-1)x = M - T  ->  x adults, y children
